/*Table structure for table `citymunicipality` */

CREATE TABLE `citymunicipality` (
  `citymuncode` varchar(10) NOT NULL,
  `citymundesc` varchar(100) NOT NULL,
  `zipcode` varchar(10) NOT NULL,
  `regioncode` varchar(10) NOT NULL,
  `provincecode` varchar(10) NOT NULL,
  `dateencoded` datetime NOT NULL,
  `encodedby` varchar(10) NOT NULL,
  `tsreference` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`citymuncode`),
  KEY `zipcode_indx` (`zipcode`),
  KEY `regioncode_indx` (`regioncode`),
  KEY `provincecode_indx` (`provincecode`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1 CHECKSUM=1 DELAY_KEY_WRITE=1 ROW_FORMAT=DYNAMIC COMMENT='List of City and Municipality';

