  `res_pk` int(11) NOT NULL,
  `notes` text,
  `is_active` enum('y','n') NOT NULL,
  `encoded_at` datetime NOT NULL,
  `encoder_pk` varchar(20) NOT NULL,
  PRIMARY KEY (`dept_res_pk`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

