/* Function  structure for function  `calc_age` */

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` FUNCTION `calc_age`(dob date) RETURNS varchar(30) CHARSET latin1
BEGIN
	DECLARE nxt VARCHAR(30);
	
	SET nxt = (SELECT YEAR(CURRENT_TIMESTAMP) - YEAR(dob) - (RIGHT(CURRENT_TIMESTAMP, 5) < RIGHT(dob, 5)) as age);
	RETURN nxt;
    END */$$
DELIMITER ;

/* Function  structure for function  `concat_nullable_string` */

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` FUNCTION `concat_nullable_string`(pStr varchar(255), pRep varchar(20)) RETURNS varchar(30) CHARSET latin1
BEGIN
	DECLARE nxt VARCHAR(30);
	
	SET nxt = (SELECT IF(pStr IS NOT NULL, CONCAT(pRep,pStr) ,''));
	RETURN nxt;
    END */$$
DELIMITER ;

/* Function  structure for function  `concat_nullable_string_end` */

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` FUNCTION `concat_nullable_string_end`(pStr varchar(255), pRep varchar(20)) RETURNS varchar(30) CHARSET latin1
BEGIN
	DECLARE nxt VARCHAR(30);
	
	SET nxt = (SELECT IF(pStr IS NOT NULL, CONCAT(pStr, pRep) ,''));
	RETURN nxt;
    END */$$
DELIMITER ;

/* Function  structure for function  `getBrgyCityMun` */

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` FUNCTION `getBrgyCityMun`(brgyCode VARCHAR(20)) RETURNS varchar(20) CHARSET utf8
BEGIN
	DECLARE id VARCHAR(20);
	
	SET id = (SELECT citymuncode FROM `psgcaddress` WHERE `barangaycode`= brgyCode);
	
	RETURN id;
    END */$$
DELIMITER ;

/* Function  structure for function  `getBrgyProvince` */

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` FUNCTION `getBrgyProvince`(brgyCode varchar(20)) RETURNS varchar(20) CHARSET utf8
BEGIN
	declare id varchar(20);
	
	set id = (select provincecode from `psgcaddress` where `barangaycode`= brgyCode);
	
	return id;
    END */$$
DELIMITER ;

/* Function  structure for function  `getBrgyRegion` */

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` FUNCTION `getBrgyRegion`(brgyCode varchar(20)) RETURNS varchar(20) CHARSET utf8
BEGIN
	declare c  varchar(20);
	
	set c = (SELECT regioncode FROM `psgcaddress` WHERE `barangaycode` = brgyCode LIMIT 1);
	
	return c;
    END */$$
DELIMITER ;

/* Function  structure for function  `get_initial_value` */

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` FUNCTION `get_initial_value`(pRemarks Varchar(255)) RETURNS varchar(30) CHARSET latin1
BEGIN
	DECLARE var_val VARCHAR(30);
	SET var_val =  (SELECT val FROM `def_val` WHERE remarks = pRemarks);
	RETURN var_val;
    END */$$
DELIMITER ;

/* Function  structure for function  `get_user_res_pk` */

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` FUNCTION `get_user_res_pk`(pUserPk Varchar(20)) RETURNS varchar(30) CHARSET latin1
BEGIN
	DECLARE id VARCHAR(30);
	SET id =  ( SELECT res_pk FROM `hosp_resident` WHERE user_pk =pUserPk);
	RETURN id;
    END */$$
DELIMITER ;

/* Function  structure for function  `next_consult_consult_req_pk` */

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` FUNCTION `next_consult_consult_req_pk`(inc_val int(11)) RETURNS varchar(30) CHARSET latin1
BEGIN
	DECLARE nxt VARCHAR(30);
	
	SET nxt = (SELECT COALESCE(CONCAT(YEAR(NOW()),MONTH(NOW()),'R',LPAD((MAX(SUBSTR(consult_req_pk,LOCATE('R',consult_req_pk) + coalesce(inc_val,1)))+COALESCE(inc_val,1)),4,0) ), CONCAT(YEAR(NOW()),MONTH(NOW()),'R','0001'))  AS nxt    FROM `consult_request`);
	RETURN nxt;
    END */$$
DELIMITER ;

/* Function  structure for function  `next_hospital_no` */

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` FUNCTION `next_hospital_no`(inc_val int(11)) RETURNS varchar(30) CHARSET latin1
BEGIN
	DECLARE nxt VARCHAR(30);
	SET nxt = (SELECT COALESCE
	(CONCAT(YEAR(NOW()),MONTH(NOW()),'P',
	LPAD((MAX(SUBSTR(hospital_no,
	LOCATE('P',hospital_no) + coalesce(inc_val,1)))+COALESCE(inc_val,1)),6,0) ),
	CONCAT(YEAR(NOW()),MONTH(NOW()),'P','000001'))  AS nxt  FROM `hosp_patient`);
	RETURN nxt;
    END */$$
DELIMITER ;

/*Table structure for table `psgcaddress` */

DROP TABLE IF EXISTS `psgcaddress`;

/*!50001 CREATE TABLE  `psgcaddress`(
 `regioncode` varchar(10) ,
 `regiondesc` varchar(100) ,
 `provincecode` varchar(10) ,
 `provincedesc` varchar(100) ,
 `citymuncode` varchar(10) ,
 `citymundesc` varchar(100) ,
 `barangaycode` varchar(10) ,
 `barangaydesc` varchar(100) ,
 `completeaddress` varchar(304) 
)*/;

/*View structure for view psgcaddress */

/*!50001 DROP TABLE IF EXISTS `psgcaddress` */;
/*!50001 CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`127.0.0.1` SQL SECURITY DEFINER VIEW `psgcaddress` AS select `p`.`regioncode` AS `regioncode`,`r`.`regiondesc` AS `regiondesc`,`c`.`provincecode` AS `provincecode`,`p`.`provincedesc` AS `provincedesc`,`b`.`citymuncode` AS `citymuncode`,`c`.`citymundesc` AS `citymundesc`,`b`.`barangaycode` AS `barangaycode`,`b`.`barangaydesc` AS `barangaydesc`,concat(`b`.`barangaydesc`,', ',`c`.`citymundesc`,', ',`p`.`provincedesc`) AS `completeaddress` from (((`barangay` `b` left join `citymunicipality` `c` on((`c`.`citymuncode` = `b`.`citymuncode`))) left join `province` `p` on((`p`.`provincecode` = `c`.`provincecode`))) left join `region` `r` on((`r`.`regioncode` = `p`.`regioncode`))) */;

